// Label text bitmap: the two label-bar strips ("DOWN"/"FIELD POSITION"/
// "YARDS TO GO" and "HOME"/"TIME REMAINING"/"VISITOR"), stored as a small
// indexed bitmap (16-color palette) rather than a full-canvas image --
// see docs/superpowers/specs/2026-07-26-bezel-overlay-design.md for the
// memory-budget rationale. Generated by tools/gen_label_bitmap.py from
// assets/bezel/overlay_400x360.png. Canvas reverted 502->400 wide after
// the 502-wide build left zero horizontal front porch on real hardware
// (whole-screen banding/ghosting) -- see docs/verification.md.
module label_rom (
    input  wire [8:0]  x,       // 0-399
    input  wire [5:0]  band_y,  // 0-57
    output wire [23:0] rgb
);
    reg [3:0]  pixel_idx [0:23199];
    initial $readmemh("label_bitmap.mem", pixel_idx);

    reg [23:0] palette [0:15];
    initial $readmemh("label_palette.mem", palette);

    // Operands explicitly widened to the 15-bit result width (max value
    // 57*400+399 = 23199, fits in 15 bits) so Verilator's -Wall self-
    // determined-width check sees no implicit expansion/truncation
    // (already hit a similar case once this project, in rom_loader.v's
    // byte_sel_rev -- see its comment).
    wire [14:0] addr = ({9'd0, band_y} * 15'd400) + {6'd0, x};
    assign rgb = palette[pixel_idx[addr]];
endmodule
